      if (name === 'MIN') return num(Math.min(...ns))
      if (name === 'MAX') return num(Math.max(...ns))
      return finite(ns.reduce((x, y) => x + y, 0) / ns.length)
    }
    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      if (args[0].n === 'range') return err('#ERR!')
      const n = toNumber(ev(args[0]))
      return n.t === 'e' ? n : num(Math.abs(n.v))
    }
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      if (args[0].n === 'range') return err('#ERR!')
      const c = ev(args[0])
      if (c.t === 'e') return c
      if (c.t === 's') return err('#VALUE!')
      const truth = c.t === 'b' ? c.v : c.v !== 0
      return ev(truth ? args[1] : args[2])
    }
    return err('#NAME?')
  }

  function ev(e) {
    switch (e.n) {
      case 'num': return num(e.v)
      case 'bool': return { t: 'b', v: e.v }
      case 'ref': return refValue(e.a)
      case 'range': return err('#ERR!')
      case 'call': return call(e)
      case 'un': {
        const n = toNumber(ev(e.e))
        if (n.t === 'e') return n
        return num(e.op === '-' ? -n.v : n.v)
