    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0].toUpperCase() }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=^*\/+\-():,])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

class Fail extends Error {}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peekOp = (...ops) => p < toks.length && toks[p].k === 'op' && ops.includes(toks[p].v)
  const fail = () => { throw new Fail() }

  function cmp() {
    let l = add()
    while (peekOp('=', '<>', '<', '<=', '>', '>=')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peekOp('+', '-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (peekOp('*', '/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (peekOp('-', '+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) fail()
    if (t.k === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.k === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!peekOp(')')) fail()
      p++
      return e
    }
    if (t.k === 'word') {
      p++
      if (peekOp('(')) {
        p++
        const args = []
        if (peekOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (peekOp(',')) { p++; continue }
            if (peekOp(')')) { p++; break }
            fail()
          }
        }
        return { n: 'call', name: t.v, args }
      }
      if (peekOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.k !== 'word') fail()
        p++
        return { n: 'range', a: t.v, b: t2.v }
      }
      if (t.v === 'TRUE') return { n: 'bool', v: true }
      if (t.v === 'FALSE') return { n: 'bool', v: false }
      return { n: 'ref', a: t.v }
    }
    return fail()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e instanceof Fail) return null
    throw e
  }
}

function rangeCells(r) {
  const a = parseAddr(r.a), b = parseAddr(r.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let w = Math.min(a.row, b.row); w <= Math.max(a.row, b.row); w++) out.push(key(c, w))
  return out
}

// ---------- evaluation ----------
function toNumber(v) {
  if (v.t === 'e') return v
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const rank = { n: 0, s: 1, b: 2 }
function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compareVals(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 's') return cpCompare(a.v, b.v)
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

function makeEvaluator(cells) {
  const memo = new Map()
  const busy = new Set()

  function cellValue(k) {
    if (memo.has(k)) return memo.get(k)
    const cell = cells.get(k)
    if (!cell) return num(0)
    if (busy.has(k)) return err('#CYCLE!')
    busy.add(k)
    let v
    try { v = literalOrFormula(cell.content) } finally { busy.delete(k) }
    memo.set(k, v)
    return v
  }

  function literalOrFormula(c) {
    if (c[0] === '=') {
      const ast = parseFormula(c.slice(1))
      return ast ? ev(ast) : err('#ERR!')
    }
    if (c === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(Number(c))
    if (ERRORS.includes(c)) return err(c)
    return { t: 's', v: c }
  }

  function refValue(a) {
    const ad = parseAddr(a)
    if (!ad) return err('#REF!')
    return cellValue(key(ad.col, ad.row))
  }

  function argValues(args) {
    const vals = []
    for (const a of args) {
      if (a.n === 'range') {
        const cs = rangeCells(a)
        if (!cs) vals.push(err('#REF!'))
        else for (const k of cs) vals.push(cellValue(k))
      } else vals.push(ev(a))
    }
    return vals
  }

  function call(e) {
    const { name, args } = e
    const agg = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (agg.includes(name)) {
      if (args.length < 1) return err('#ERR!')
      const vals = argValues(args)
      const bad = vals.find((v) => v.t === 'e')
      if (bad) return bad
      if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
      const ns = []
      for (const v of vals) {
        const n = toNumber(v)
        if (n.t === 'e') return n
        ns.push(n.v)
      }
      if (name === 'SUM') return finite(ns.reduce((x, y) => x + y, 0))
      if (name === 'MIN') return num(Math.min(...ns))
      if (name === 'MAX') return num(Math.max(...ns))
      return finite(ns.reduce((x, y) => x + y, 0) / ns.length)
    }
    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      if (args[0].n === 'range') return err('#ERR!')
      const n = toNumber(ev(args[0]))
      return n.t === 'e' ? n : num(Math.abs(n.v))
    }
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      if (args[0].n === 'range') return err('#ERR!')
      const c = ev(args[0])
      if (c.t === 'e') return c
      if (c.t === 's') return err('#VALUE!')
      const truth = c.t === 'b' ? c.v : c.v !== 0
      return ev(truth ? args[1] : args[2])
    }
    return err('#NAME?')
  }

  function ev(e) {
    switch (e.n) {
      case 'num': return num(e.v)
      case 'bool': return { t: 'b', v: e.v }
      case 'ref': return refValue(e.a)
      case 'range': return err('#ERR!')
      case 'call': return call(e)
      case 'un': {
        const n = toNumber(ev(e.e))
        if (n.t === 'e') return n
        return num(e.op === '-' ? -n.v : n.v)
      }
      case 'bin': {
        const l = ev(e.l), r = ev(e.r)
        if (l.t === 'e') return l
        if (r.t === 'e') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(e.op)) {
          const c = compareVals(l, r)
          const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[e.op]
          return { t: 'b', v: res }
        }
        const a = toNumber(l)
        if (a.t === 'e') return a
        const b = toNumber(r)
        if (b.t === 'e') return b
        switch (e.op) {
          case '+': return finite(a.v + b.v)
          case '-': return finite(a.v - b.v)
          case '*': return finite(a.v * b.v)
          case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
          default: return finite(Math.pow(a.v, b.v))
        }
      }
    }
    return err('#ERR!')
  }
  return cellValue
}

function sortedCells(cells) {
  return [...cells.entries()].sort((x, y) => x[1].col - y[1].col || x[1].row - y[1].row)
}

function fmt(v) {
  if (v.t === 'n') return String(Number(v.v.toPrecision(10)))
  if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

export function runValues(cells) {
  const cv = makeEvaluator(cells)
  let out = ''
  for (const [k] of sortedCells(cells)) out += `${k}=${fmt(cv(k))}\n`
  return out
}

function collect(e, set) {
  switch (e.n) {
    case 'ref': { const a = parseAddr(e.a); if (a) set.add(key(a.col, a.row)); break }
    case 'range': { const cs = rangeCells(e); if (cs) cs.forEach((k) => set.add(k)); break }
    case 'un': collect(e.e, set); break
    case 'bin': collect(e.l, set); collect(e.r, set); break
    case 'call': e.args.forEach((a) => collect(a, set)); break
  }
}

export function runDeps(cells) {
  let out = ''
  for (const [k, cell] of sortedCells(cells)) {
    const set = new Set()
    if (cell.content[0] === '=') {
      const ast = parseFormula(cell.content.slice(1))
      if (ast) collect(ast, set)
    }
    const list = [...set].map((s) => parseAddr(s) && { s, ...parseAddr(s) })
    list.sort((x, y) => x.col - y.col || x.row - y.row)
    out += `${k}:${list.map((x) => ' ' + x.s).join('')}\n`
  }
  return out
}
"}

